from collections import defaultdict

N = 200010
h = [-1] * N
ne = [0] * (N * 2)
e = [0] * (N * 2)
idx = 0
dp = [0] * N
sum = [0] * N
tiao = [0] * N
tt = [0] * N
ans = 0
n = int(input())

def add(a, b):
    global idx
    e[idx] = b
    ne[idx] = h[a]
    h[a] = idx
    idx += 1

def dfs_zong(u, fa):
    sum[u] = 1
    tiao[u] = 1
    i=h[u]
    while i!=-1:
        j = e[i]
        if j == fa:
            i=ne[i]
            continue
        dfs_zong(j, u)
        sum[u] += sum[j]
        dp[u] += dp[j] + (n - sum[j]) * sum[j] * 2
        if u != 1:
            tiao[fa] += tiao[j]
        tt[u] += tiao[j]
        i=ne[i]

def dfs_jian(u, fa):
    global ans
    i=h[u]
    while i!=-1:
        j = e[i]
        if j == fa:
            i=ne[i]
            continue
        dfs_jian(j, u)
        ans -= tiao[j] * (tt[u] - tiao[j])
        if u != 1:
            ans -= tiao[j] * (n - sum[u]) * 2
        i=ne[i]
for _ in range(n-1):
    a, b = map(int,input().split(' '))
    add(a, b)
    add(b, a)
dfs_zong(1, -1)
ans = dp[1]
dfs_jian(1, -1)
