### java
```java
import java.util.*;

public class Main {
    static final int N = 200010;
    static long n;
    static long[] h = new long[N];
    static long[] ne = new long[N * 2];
    static long[] e = new long[N * 2];
    static long idx;
    static long[] dp = new long[N];
    static long[] sum = new long[N];
    static long[] tiao = new long[N];
    static long[] tt = new long[N];
    static long ans;

    public static void add(int a, int b) {
        e[(int)idx] = b;
        ne[(int)idx] = h[a];
        h[a] = idx++;
    }

    public static void dfs_zong(int u, int fa) {
        sum[u] = 1;
        tiao[u] = 1;
        for (int i = (int)h[u]; i != -1; i = (int)ne[i]) {
            int j = (int)e[i];
            if (j == fa) continue;
            dfs_zong(j, u);
            sum[u] += sum[j];
            dp[u] += dp[j] + (n - sum[j]) * sum[j] * 2;
            if (u != 1) {
                tiao[fa] += tiao[j];
            }
            tt[u] += tiao[j];
        }
    }

    public static void dfs_jian(int u, int fa) {
        for (int i = (int)h[u]; i != -1; i = (int)ne[i]) {
            int j = (int)e[i];
            if (j == fa) continue;
            dfs_jian(j, u);
            ans -= tiao[j] * (tt[u] - tiao[j]);
            if (u != 1) {
                ans -= tiao[j] * (n - sum[u]) * 2;
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextLong();
        Arrays.fill(h, -1);

        for (int i = 0; i < n - 1; i++) {
            int a = scanner.nextInt();
            int b = scanner.nextInt();
            add(a, b);
            add(b, a);
        }

        dfs_zong(1, -1);
        ans = dp[1];
        dfs_jian(1, -1);
        System.out.println(ans);
    }
}
